import 'package:flutter/services.dart'; class DeviceCapabilities { final int androidSdk; final bool rootAvailable; final bool appInventoryAvailable; final bool advancedEnvironmentAvailable; const DeviceCapabilities({ required this.androidSdk, required this.rootAvailable, required this.appInventoryAvailable, required this.advancedEnvironmentAvailable, }); String get androidVersion { if (androidSdk >= 35) return 'Android 15 أو أحدث'; if (androidSdk >= 34) return 'Android 14'; if (androidSdk >= 33) return 'Android 13'; if (androidSdk >= 32) return 'Android 12L'; if (androidSdk >= 31) return 'Android 12'; if (androidSdk >= 30) return 'Android 11'; if (androidSdk >= 29) return 'Android 10'; if (androidSdk >= 28) return 'Android 9'; return 'Android SDK $androidSdk'; } String get recommendedLevel { if (rootAvailable && advancedEnvironmentAvailable) { return 'الباحث المتقدم'; } if (appInventoryAvailable) { return 'الفحص الموسّع'; } return 'الفحص الأساسي'; } factory DeviceCapabilities.fromMap(Map<Object?, Object?> map) { return DeviceCapabilities( androidSdk: (map['androidSdk'] as num?)?.toInt() ?? 0, rootAvailable: map['rootAvailable'] == true, appInventoryAvailable: map['appInventoryAvailable'] == true, advancedEnvironmentAvailable: map['advancedEnvironmentAvailable'] == true, ); } } class DeviceCapabilitiesService { static const MethodChannel _channel = MethodChannel('com.nathr.security/device'); Future<DeviceCapabilities> inspect() async { final result = await _channel.invokeMethod<Map<dynamic, dynamic>>( 'getDeviceCapabilities', ); if (result == null) { throw StateError('لم تُرجع خدمة أندرويد معلومات الجهاز'); } return DeviceCapabilities.fromMap(result); } } 